-- Purpose: FORECAST training set. Plant HZL_DEMO_01, ZSPR and ZSPN materials, one row per material x month, 2023-01..2025-12 (36 months, empty months 0).
--   Target NET_CONSUMPTION_QTY = issues 261 minus reversals 262. Covariates: MATERIAL_TYPE (DIM_MATERIAL.MATERIAL_TYPE), PLANNED_MAINT_QTY, PLANNED_SHUTDOWN_QTY,
--   PLANT_SHUTDOWN_FLAG, SEASON_INDEX, MONTH_OF_YEAR.
-- Result rows: 214560 (5960 series x 36 months; ZSPR 3707 series / 133452 rows, ZSPN 2253 series / 81108 rows)
-- Data asset id: 6b06d4af5be48659f48aca60 (sync 1cd81896-a42b-40a7-96dd-38715a99bedb, t2f-fcst-hzl01-train-20261125-1957)
WITH MV AS (SELECT MATERIAL_ID, PLANT_ID, POSTING_DATE, MOVEMENT_TYPE, QUANTITY FROM VEDANTA_POC.FACT_MATERIAL_MOVEMENT_PART_001 UNION ALL SELECT MATERIAL_ID, PLANT_ID, POSTING_DATE, MOVEMENT_TYPE, QUANTITY FROM VEDANTA_POC.FACT_MATERIAL_MOVEMENT_PART_002 UNION ALL SELECT MATERIAL_ID, PLANT_ID, POSTING_DATE, MOVEMENT_TYPE, QUANTITY FROM VEDANTA_POC.FACT_MATERIAL_MOVEMENT_PART_003 UNION ALL SELECT MATERIAL_ID, PLANT_ID, POSTING_DATE, MOVEMENT_TYPE, QUANTITY FROM VEDANTA_POC.FACT_MATERIAL_MOVEMENT_PART_004),
CONS AS (SELECT MV.MATERIAL_ID, TO_DATE(TO_VARCHAR(MV.POSTING_DATE,'YYYY-MM')||'-01') AS M, SUM(CASE WHEN MV.MOVEMENT_TYPE='261' THEN MV.QUANTITY WHEN MV.MOVEMENT_TYPE='262' THEN -MV.QUANTITY ELSE 0 END) AS NET_QTY FROM MV JOIN VEDANTA_POC.DIM_MATERIAL DM ON DM.MATERIAL_ID=MV.MATERIAL_ID WHERE MV.PLANT_ID='HZL_DEMO_01' AND DM.MATERIAL_TYPE IN ('ZSPR','ZSPN') AND MV.MOVEMENT_TYPE IN ('261','262') AND MV.POSTING_DATE >= '2023-01-01' AND MV.POSTING_DATE <= '2025-12-31' GROUP BY MV.MATERIAL_ID, TO_DATE(TO_VARCHAR(MV.POSTING_DATE,'YYYY-MM')||'-01')),
SERIES AS (SELECT DISTINCT MATERIAL_ID FROM CONS),
MONTHS AS (SELECT TO_DATE(GENERATED_PERIOD_START) AS M FROM SERIES_GENERATE_TIMESTAMP('INTERVAL 1 MONTH','2023-01-01 00:00:00','2026-01-01 00:00:00')),
MAINT AS (SELECT FR.MATERIAL_ID, TO_DATE(TO_VARCHAR(MO.REQUIREMENT_DATE,'YYYY-MM')||'-01') AS M, SUM(FR.REQUIRED_QTY) AS Q FROM VEDANTA_POC.FACT_MAINTENANCE_REQUIREMENT FR JOIN VEDANTA_POC.DIM_MAINTENANCE_ORDER MO ON MO.MAINTENANCE_ORDER_ID=FR.MAINTENANCE_ORDER_ID JOIN VEDANTA_POC.DIM_EQUIPMENT EQ ON EQ.EQUIPMENT_ID=MO.EQUIPMENT_ID WHERE EQ.PLANT_ID='HZL_DEMO_01' GROUP BY FR.MATERIAL_ID, TO_DATE(TO_VARCHAR(MO.REQUIREMENT_DATE,'YYYY-MM')||'-01')),
SHUT AS (SELECT FS.MATERIAL_ID, TO_DATE(TO_VARCHAR(SE.PLANNED_START_DATE,'YYYY-MM')||'-01') AS M, SUM(FS.REQUIRED_QTY) AS Q FROM VEDANTA_POC.FACT_SHUTDOWN_SCHEDULE FS JOIN VEDANTA_POC.DIM_SHUTDOWN_EVENT SE ON SE.SHUTDOWN_ID=FS.SHUTDOWN_ID WHERE SE.PLANT_ID='HZL_DEMO_01' GROUP BY FS.MATERIAL_ID, TO_DATE(TO_VARCHAR(SE.PLANNED_START_DATE,'YYYY-MM')||'-01')),
SHM AS (SELECT DISTINCT MO2.M FROM MONTHS MO2 JOIN VEDANTA_POC.DIM_SHUTDOWN_EVENT SE ON SE.PLANNED_START_DATE < ADD_MONTHS(MO2.M,1) AND SE.PLANNED_END_DATE >= MO2.M WHERE SE.PLANT_ID='HZL_DEMO_01'),
SEAS AS (SELECT MATERIAL_GROUP, CALENDAR_MONTH_NO, COALESCE(MANUAL_OVERRIDE_INDEX, SEASON_INDEX_DERIVED) AS SI FROM VEDANTA_POC.SEASONALITY_INPUT WHERE PLANT_ID='HZL_DEMO_01')
SELECT S.MATERIAL_ID || '|HZL_DEMO_01' AS SERIES_ID, TO_VARCHAR(MO.M,'YYYY-MM-DD') AS MONTH_START, COALESCE(C.NET_QTY,0) AS NET_CONSUMPTION_QTY, DMM.MATERIAL_TYPE AS MATERIAL_TYPE, COALESCE(MA.Q,0) AS PLANNED_MAINT_QTY, COALESCE(SH.Q,0) AS PLANNED_SHUTDOWN_QTY, CASE WHEN SM.M IS NULL THEN 0 ELSE 1 END AS PLANT_SHUTDOWN_FLAG, COALESCE(SE2.SI,1) AS SEASON_INDEX, MONTH(MO.M) AS MONTH_OF_YEAR FROM SERIES S CROSS JOIN MONTHS MO LEFT JOIN CONS C ON C.MATERIAL_ID=S.MATERIAL_ID AND C.M=MO.M LEFT JOIN MAINT MA ON MA.MATERIAL_ID=S.MATERIAL_ID AND MA.M=MO.M LEFT JOIN SHUT SH ON SH.MATERIAL_ID=S.MATERIAL_ID AND SH.M=MO.M LEFT JOIN SHM SM ON SM.M=MO.M JOIN VEDANTA_POC.DIM_MATERIAL DMM ON DMM.MATERIAL_ID=S.MATERIAL_ID LEFT JOIN SEAS SE2 ON SE2.MATERIAL_GROUP=DMM.MATERIAL_GROUP AND SE2.CALENDAR_MONTH_NO=MONTH(MO.M) ORDER BY 1,2
